import fs from'node:fs';import cp from'node:child_process';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';
const[repo,out]=process.argv.slice(2),sha=b=>createHash('sha256').update(b).digest('hex'),blob=(pin,p)=>cp.execFileSync('git',['cat-file','blob',pin+':'+p],{cwd:repo,maxBuffer:64e6});
const specs=[['agency-business-entry-inline-source-forward-20261014','4c26565f68521fa868b211ce36ba22a9471053c0','construction/business-inline.test.mjs',58],['agency-off-native-transport-forward-20261015','fee53465a85b6c8fa7ac059d225429022db7260a','off-agency-transport.test.mjs',83]],base=i=>'docs/healthroster-build/proposals/'+specs[i][0]+'/';
function seal(){return specs.map(([dir,pin],i)=>{const raw=blob(pin,base(i)+'REVIEW_MANIFEST.json'),m=JSON.parse(raw);for(const e of [...m.entries,{path:'REVIEW_MANIFEST.json'}]){const b=blob(pin,base(i)+e.path);assert.deepEqual(b,fs.readFileSync(path.join(repo,base(i),e.path)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{dir,commit:pin,files:m.entries.length+1,manifest_sha256:sha(raw)};});}
fs.mkdirSync(out,{recursive:true});const before=seal();let owners=0,hunks=0,pins=0,normalised_predecessors=0;
const one=JSON.parse(blob(specs[0][1],base(0)+'construction/BUSINESS_ENTRY_CURRENT_REVERSES.json'));for(const r of one.reverses){let s=blob(specs[0][1],base(0)+'construction/'+r.output).toString();assert.equal(sha(s),r.forward_sha256);for(const h of [...r.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}const p=blob('63965738af6f148a75cd1bea5052600e4b007da5',r.input_path);assert.deepEqual(Buffer.from(s),p);assert.equal(sha(s),r.input_sha256);if(!p.equals(Buffer.from(s)))normalised_predecessors++;owners++;pins++;}
const recipe=JSON.parse(blob(specs[0][1],base(0)+'FINAL_COMPOSITION_RECIPE.json'));for(const p of recipe.dependencies){const b=blob(p.commit,p.path);assert.equal(b.length,p.bytes);assert.equal(sha(b),p.sha256);pins++;}
const off=JSON.parse(blob(specs[1][1],base(1)+'OFF_AGENCY_COMPLETE_REVERSES.json'));for(const p of off.pins){const b=blob(p.pin,p.path);assert.equal(b.length,p.bytes);assert.equal(sha(b),p.raw_sha256);pins++;}
for(const r of off.reverses){let s=blob(specs[1][1],base(1)+r.output).toString();assert.equal(sha(s),r.after_sha256);for(const h of [...r.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}const matches=off.pins.filter(p=>sha(blob(p.pin,p.path).toString().replaceAll('\r\n','\n'))===r.before_sha256);assert.equal(matches.length,1,r.output+' actual predecessor');const p=blob(matches[0].pin,matches[0].path);assert.equal(s,p.toString().replaceAll('\r\n','\n'));if(!p.equals(Buffer.from(s)))normalised_predecessors++;owners++;}
assert.equal(owners,12);assert.equal(hunks,42);
const actual=JSON.parse(blob(specs[1][1],base(1)+'ACTUAL_AGENCY_PUBLIC_OWNER_INPUTS.json'));const parser=blob('fee53465a85b6c8fa7ac059d225429022db7260a','docs/healthroster-build/proposals/agency-fixed-approval-policy-support-20261015/reference/pinned-source-parser.mjs');const{functionEvents}=await import('data:text/javascript;base64,'+parser.toString('base64'));
assert.equal(actual.native_owner_input_pins.length,7);for(const p of actual.native_owner_input_pins){const b=blob(p.pin,p.path);assert.equal(b.length,p.bytes);assert.equal(sha(b),p.raw_sha256);const defs=functionEvents(b.toString().replaceAll('\r\n','\n')).events.filter(e=>e.kind==='CREATE'&&e.id===p.signature);assert.equal(defs.length,1);assert.equal(sha(defs[0].definition),p.definition_sha256);pins++;}
const tests=[];for(const[i,s]of specs.entries()){const file=base(i)+s[2],r=cp.spawnSync(process.execPath,['--test','--test-reporter=tap',file],{cwd:repo,encoding:'utf8',maxBuffer:8e6}),b=Buffer.from(r.stdout+r.stderr);fs.writeFileSync(path.join(out,path.basename(s[2])+'.tap.txt'),b);assert.equal(r.status,0);assert.match(b.toString(),new RegExp('# pass '+s[3]+'\\b'));assert.match(b.toString(),/# fail 0\b/);tests.push({file,cases:s[3],output_sha256:sha(b)});}
const checks={source_only:true,native:false,mount_ready:false,before,after:seal(),whole_owner_reverses:owners,unique_hunks:hunks,actual_source_pins:pins,declared_crlf_to_lf_owner_predecessors:normalised_predecessors,raw_saved_git_artifacts_exact:true,actual_public_signatures:7,tests,raw_whitespace_pass:false,inherited_whitespace_findings:528,text_codec_final_successor_required:'267e0b5b7b535d6eda4bb646ff54b93ad2ecbdda',unrun:['current whole root owner/caller/ACL/registry/contract union','real private OFF scope/admission/PID/XID/audit/native-result proof','actual MANUAL/targeted worker/native Authorise/Return and protected history/Original/NX-AI-6/Report NONE','complete native financial/API/Office/app/phone acceptance']};fs.writeFileSync(path.join(out,'CHECKS.json'),JSON.stringify(checks,null,2)+'\n');console.log(JSON.stringify(checks));
